    "summary": "Imperial eulogy (Prashasti) or royal decree of Yashodharman of Malwa regarding Sondani Victory Pillars at Mandsaur: Crushing Defeat of Mihirakula, documenting the Golden Age of Indian literature, science (Aryabhata), and universal education.",
    "historicalContext": "Promulgated during the Gupta Classical Renaissance (c. 528 AD), renowned for political stability, low taxation, and religious pluralism.",
    "fullExcerptText": "The Maharajadhiraja, whose arm was decorated with the luster of a hundred wounds received in righteous battle, whose treasury was spent on building monasteries and temples, whose compassion relieved the afflictions of all who sought his refuge! By his sovereign decree, let lands and villages be endowed unto the great academy of Nalanda forever, that students from China, Tibet, and Hellas may learn without fee or hindrance!",
